-- Inventory stocktake sessions and count snapshots.
CREATE TABLE IF NOT EXISTS inventory_stocktakes (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE, branch_id UUID REFERENCES branches(id) ON DELETE SET NULL, warehouse_id UUID NOT NULL, reference VARCHAR(120), notes VARCHAR(2000), status VARCHAR(16) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted','cancelled')), created_by UUID REFERENCES users(id) ON DELETE SET NULL, posted_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), posted_at TIMESTAMPTZ, CONSTRAINT inventory_stocktakes_id_company_unique UNIQUE(id,company_id), CONSTRAINT inventory_stocktakes_warehouse_company_fk FOREIGN KEY(warehouse_id,company_id) REFERENCES warehouses(id,company_id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_inventory_stocktakes_one_draft_per_warehouse ON inventory_stocktakes(company_id,warehouse_id) WHERE status='draft';
CREATE INDEX IF NOT EXISTS idx_inventory_stocktakes_company_created ON inventory_stocktakes(company_id,created_at DESC);
CREATE TABLE IF NOT EXISTS inventory_stocktake_lines (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE, stocktake_id UUID NOT NULL, product_id UUID NOT NULL, snapshot_quantity NUMERIC(16,4) NOT NULL DEFAULT 0 CHECK(snapshot_quantity>=0), counted_quantity NUMERIC(16,4) CHECK(counted_quantity>=0), counted_at TIMESTAMPTZ, average_unit_cost NUMERIC(16,4) NOT NULL DEFAULT 0 CHECK(average_unit_cost>=0), notes VARCHAR(2000), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT inventory_stocktake_lines_session_company_fk FOREIGN KEY(stocktake_id,company_id) REFERENCES inventory_stocktakes(id,company_id) ON DELETE CASCADE, CONSTRAINT inventory_stocktake_lines_product_company_fk FOREIGN KEY(product_id,company_id) REFERENCES products(id,company_id) ON DELETE RESTRICT, CONSTRAINT inventory_stocktake_lines_session_product_unique UNIQUE(stocktake_id,product_id));
CREATE INDEX IF NOT EXISTS idx_inventory_stocktake_lines_company_session ON inventory_stocktake_lines(company_id,stocktake_id);
ALTER TABLE inventory_stocktakes ENABLE ROW LEVEL SECURITY;
ALTER TABLE inventory_stocktake_lines ENABLE ROW LEVEL SECURITY;
